	return nil
}

func TestSeedSampleWorkspace_PropagatesCreateError(t *testing.T) {
	if err := SeedSampleWorkspace(context.Background(), errWS{}, "user-1"); err == nil {
		t.Fatal("expected error from CreateWorkspace failure")
	}
}

